<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStoreKey;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Infrastructure\Connector\FileStorage\PdoFileStorage;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Connector\Pdo\SnippetAssetPdoConnector;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetReadGateway;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetSlide;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetFilter;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetCursor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAssetRef;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAsset;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetAssetReadRepositoryAdapter implements SnippetAssetReadGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly PdoFileStorage $store,
        private readonly SnippetAssetPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(SnippetAssetRef $ref): ?SnippetAsset
    {
        if ($ref instanceof SnippetAsset) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new SnippetAssetFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?SnippetAssetFilter $filter = null, ?SnippetAssetCursor $cursor = null): SnippetAssetSlide
    {
        $this->logDebug("List for Snippet asset on adapter ");
        $span = $this->startSpan("List for Snippet asset on adapter");
        try {
            $values = $this->conn->list($filter, $cursor);
            $last = end($values);
            return new SnippetAssetSlide(function (SnippetAssetFilter $slide, ?SnippetAssetCursor $next) use ($filter) {
                return $this->list($filter, $next);
            }, new SnippetAssetCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(SnippetAssetFilter $filter): ?SnippetAsset
    {
        $this->logDebug("Retrieve for Snippet asset on adapter ");
        $span = $this->startSpan("Retrieve for Snippet asset on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(SnippetAssetFilter $filter): bool
    {
        $this->logDebug("Exists for Snippet asset on adapter ");
        $span = $this->startSpan("Exists for Snippet asset on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?SnippetAssetFilter $filter = null): int
    {
        $this->logDebug("Count for Snippet asset on adapter ");
        $span = $this->startSpan("Count for Snippet asset on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function readContent(string $key): BinaryContent
    {
        $this->logDebug("Load Content childs for Snippet asset on adapter ");
        $span = $this->startSpan("Load Content childs for Snippet asset on adapter");
        try {
            $binary = $this->store->retrieveFile(new FileStoreKey($key));
            if ($binary) {
                return $binary;
            } else {
                throw new NotFoundException('');
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByCodeAndSnippet(string $code, SnippetRef $snippet): ?SnippetAsset
    {
        $this->logDebug("Find on by code snippet for Snippet asset on adapter");
        $span = $this->startSpan("Find on by code snippet for Snippet asset on adapter");
        try {
            return $this->conn->retrieve(new SnippetAssetFilter(codeAndSnippet: SnippetAssetFilter::codeAndSnippetFilter(code: $code, snippet: $snippet)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
